    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "Can it track Schengen 90/180 and custom limits?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. AtlasDays supports rolling windows, per-stay limits, calendar-year counting, and custom trackers."
        }
      },
      {
        "@type": "Question",
        "name": "Is AtlasDays free?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. The core day tracking, trips, one tracker, and the map are free with no account required. AtlasDays Pro is an optional upgrade, available as a quarterly or annual subscription or a one-time lifetime purchase, that adds unlimited trackers, Smart Alerts, exports, and more."
        }
      },
      {
        "@type": "Question",
        "name": "Is there an Android version?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "No. AtlasDays is iOS only for now."
        }
      },
      {
        "@type": "Question",
        "name": "Is this legal or tax advice?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "No. AtlasDays helps you keep records and count days. Interpretation of immigration or tax rules is still your responsibility."
        }
      },
      {
        "@type": "Question",
        "name": "Does it store my precise location?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "No. Country detection is optional and designed around country suggestions, not continuous location surveillance."
        }
      },
      {
        "@type": "Question",
        "name": "Can I import and export travel history?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. AtlasDays supports Photo Import from geotagged photo metadata, CSV import, Flighty flight-history import, CSV export, and PDF travel reports. Photo, CSV, and Flighty imports show a review step before trips are saved."
        }
      },
      {
        "@type": "Question",
        "name": "Can I add older trips with incomplete dates?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. AtlasDays supports exact trips, year-only entries, and unknown-date visits. Approximate history stays useful without turning into fake precision."
        }
      },
      {
        "@type": "Question",
        "name": "Does it work offline?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Your trips, trackers, and map stay available on-device without an internet connection."
        }
      },
      {
        "@type": "Question",
        "name": "Why does location access need to be set to \"Always\"?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Automatic country detection uses iOS Significant Location Changes, which only fires in the background, when you actually cross a border. \"When In Use\" only works while the app is open, so it would miss most arrivals. The feature is optional; you can use AtlasDays entirely by logging trips manually."
        }
      },
      {
        "@type": "Question",
        "name": "Are there Home Screen widgets?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. AtlasDays includes Home Screen widgets in small, medium, and large sizes. You can add a tracker widget that shows days used, days remaining, and a forecast, or a world map widget. Multiple widgets can be added to show different trackers side by side."
        }
      }
